const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const seed={suppliers:[{id:'SUP011',name:'ANUGERAH WAHYUDI SEJAHTERA'},{id:'SUP002',name:'PT. Sumber Rezeki'},{id:'SUP003',name:'CV. Maju Jaya'}],products:[{id:'8996001234567',name:'Saus Sambal ABC',supplier:'SUP011',emoji:'🌶️'},{id:'8996007654321',name:'Kecap Manis Bango',supplier:'SUP011',emoji:'🍶'},{id:'8992711234567',name:'Tepung Terigu Segitiga Biru',supplier:'SUP002',emoji:'🌾'},{id:'8992717654321',name:'Gula Pasir Gulaku',supplier:'SUP002',emoji:'🍚'},{id:'8992719876543',name:'Mentega Blue Band',supplier:'SUP003',emoji:'🧈'}],orders:[],activities:[]};
seed.orders=[['002','2026-10-22','SUP011','Draft',[18,12]],['001','2026-10-21','SUP002','Sent',[20,15]],['003','2026-10-20','SUP003','Confirmed',[24,10]],['004','2026-10-18','SUP011','Draft',[10,8]],['005','2026-10-16','SUP002','Delivered',[12,6]]].map(([id,date,supplier,status,qty])=>({id:'PO-'+date.replaceAll('-','')+'-'+id,date,arrival:date,supplier,status,items:seed.products.filter(p=>p.supplier===supplier).map((p,i)=>({product:p.id,qty:qty[i]||10}))}));
seed.activities=[{text:'PO-20261022-002 dibuat',detail:'ANUGERAH WAHYUDI SEJAHTERA',date:'2026-10-22T10:24:00'},{text:'Produk baru ditambahkan',detail:'Master produk siap digunakan',date:'2026-10-22T08:15:00'},{text:'PO-20261021-001 dikirim',detail:'PT. Sumber Rezeki',date:'2026-10-21T14:00:00'}];
let db;try{db=JSON.parse(localStorage.getItem('upu-po-v1'))||structuredClone(seed)}catch{db=structuredClone(seed)}let page='home',filter='Semua',query='',selected='',imported=[];
const menus=[['home','⌂','Beranda'],['orders','▤','Purchase Order'],['import','⇩','Import Excel'],['suppliers','♧','Supplier'],['products','▣','Produk']];
const supplier=id=>db.suppliers.find(s=>s.id===id)?.name||id,product=id=>db.products.find(p=>p.id===id)?.name||id,total=o=>o.items.reduce((s,i)=>s+Number(i.qty),0),date=d=>new Date(d+'T00:00:00').toLocaleDateString('id-ID',{day:'numeric',month:'short',year:'numeric'}),today=()=>new Date().toLocaleDateString('en-CA'),badge=s=>`<span class="badge ${esc(s)}">${esc(s)}</span>`;
function save(){try{localStorage.setItem('upu-po-v1',JSON.stringify(db))}catch{toast('Penyimpanan browser penuh. Ekspor cadangan data.')}}function log(text,detail){db.activities.unshift({text,detail,date:new Date().toISOString()});save()}function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.tt);window.tt=setTimeout(()=>$('#toast').style.display='none',3500)}
function navigate(p){page=p;query='';filter='Semua';render();window.scrollTo(0,0)}function heading(title,sub,buttons=''){return `<div class="page-heading"><div><span class="eyebrow">PURCHASE ORDER MANAGEMENT</span><h1>${title}</h1><p class="sub">${sub}</p></div><div class="buttons">${buttons}</div></div>`}const newBtn=`<button class="btn primary" onclick="orderForm()">＋ Buat Purchase Order</button>`;
function render(){const active=page==='detail'?'orders':page;$('#sidebar').innerHTML=`<div class="logo"><span class="logo-icon">🛒</span><div><b>Kedai UPU PO</b><small>PURCHASING WORKSPACE</small></div></div><div class="nav-label">MENU UTAMA</div>${menus.map(([id,icon,label])=>`<button class="navitem ${active===id?'active':''}" onclick="navigate('${id}')"><span class="symbol">${icon}</span>${label}</button>`).join('')}<div class="nav-label">WORKSPACE</div><button class="navitem ${page==='activity'?'active':''}" onclick="navigate('activity')"><span class="symbol">◷</span>Aktivitas Terbaru</button><div class="sidebar-bottom"><div class="help"><b>Lebih rapi, lebih produktif.</b><p>Satukan pembelian dan supplier dalam satu tempat.</p><button class="text-link" onclick="navigate('import')">Mulai impor Excel →</button></div><button class="navitem" onclick="navigate('profile')"><span class="avatar">TP</span>Tim Purchasing　›</button></div>`;$('#bottom').innerHTML=menus.map(([id,icon,label])=>`<button class="${active===id?'active':''}" onclick="navigate('${id}')"><span class="symbol">${icon}</span>${id==='orders'?'PO':id==='import'?'Import':label}</button>`).join('');$('#crumb').textContent=menus.find(m=>m[0]===active)?.[2]||({activity:'Aktivitas Terbaru',profile:'Profil'}[page]);({home:home,orders:orders,detail:detail,import:importPage,suppliers:master,products:master,activity:activityPage,profile:profile})[page]()}
function rows(list){return list.map(o=>`<tr class="clickable" tabindex="0" onclick="openOrder('${o.id}')" onkeydown="if(event.key==='Enter')openOrder('${o.id}')"><td><strong>${esc(o.id)}</strong><small>${date(o.date)}</small></td><td><strong>${esc(supplier(o.supplier))}</strong><small>${esc(o.supplier)}</small></td><td>${o.items.length} item</td><td>${total(o)} qty</td><td>${badge(o.status)}</td><td style="color:#8e9db3">›</td></tr>`).join('')}
function table(list){return list.length?`<div class="table-wrap po-table"><table><thead><tr><th>Nomor PO / Tanggal</th><th>Supplier</th><th>Jumlah Item</th><th>Total Qty</th><th>Status</th><th></th></tr></thead><tbody>${rows(list)}</tbody></table></div>`:`<div class="empty"><span class="symbol">▤</span><h2>Belum ada Purchase Order</h2><p>Buat PO baru atau sesuaikan pencarian Anda.</p><button class="btn primary" onclick="orderForm()">＋ Buat PO</button></div>`}
function activityList(limit=100){return `<div class="activity-list">${db.activities.slice(0,limit).map(a=>`<div class="activity"><strong>${esc(a.text)}</strong><small>${esc(a.detail)}</small><time>${new Date(a.date).toLocaleString('id-ID',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}</time></div>`).join('')||'<p class="sub">Belum ada aktivitas.</p>'}</div>`}
function home(){$('#main').innerHTML=heading('Ringkasan aktivitas','Pantau dan kelola seluruh pembelian Anda dalam satu tempat.',`<button class="btn" onclick="navigate('import')">⇩ Import Excel</button>${newBtn}`)+`<div class="welcome"><div><span class="eyebrow">SELAMAT DATANG KEMBALI</span><h2>Halo, Tim Purchasing 👋</h2><p>Semua kebutuhan pembelian, dalam kendali Anda.<br>Mari mulai hari yang produktif bersama Kedai UPU.</p></div><div class="welcome-art">🛒</div></div><div class="stats">${[['▤','Total Purchase Order',db.orders.length,'PO tercatat'],['▣','Total Supplier',db.suppliers.length,'partner pembelian'],['◈','Total Produk',db.products.length,'produk terdaftar'],['♧','Total Kuantitas',db.orders.reduce((s,o)=>s+total(o),0),'unit di seluruh PO']].map(([icon,title,note,caption])=>`<div class="stat"><div class="stat-top"><span class="stat-icon">${icon}</span>${title}</div><strong>${note}</strong><small><em>●</em> ${caption}</small></div>`).join('')}</div><div class="columns"><section class="panel"><div class="panel-head"><h2>Purchase Order Terbaru</h2><button class="text-link" onclick="navigate('orders')">Lihat semua →</button></div>${table(db.orders.slice(0,5))}</section><div class="right-column"><section class="panel"><div class="panel-head"><h2>Aktivitas Terbaru</h2><button class="text-link" onclick="navigate('activity')">Lihat semua →</button></div>${activityList(3)}</section><section class="panel quick"><span class="eyebrow">CARA CEPAT BUAT PO</span><h3 style="margin-top:10px">Dari Excel, jadi Purchase Order.</h3><p>Unggah daftar barang Anda dan buat PO otomatis per supplier.</p><button class="btn" onclick="navigate('import')">⇩ Import data Excel →</button></section></div></div><div class="section-note">◉ Data tersimpan di browser perangkat ini · Data awal merupakan contoh</div>`}
function orders(){$('#main').innerHTML=heading('Purchase Order','Kelola dan pantau pesanan pembelian Anda.',newBtn)+`<div class="toolbar"><input class="search" placeholder="⌕ Cari nomor PO atau supplier..." aria-label="Cari purchase order" oninput="query=this.value;updateOrders()"><button class="btn" onclick="exportOrders()">↓ Ekspor CSV</button></div><section class="panel"><div class="filters">${['Semua','Draft','Sent','Confirmed','Delivered'].map(s=>`<button class="chip ${s===filter?'active':''}" onclick="setFilter('${s}',this)">${s}</button>`).join('')}</div><div id="orders-list"></div></section>`;updateOrders()}
function setFilter(s,el){filter=s;document.querySelectorAll('.chip').forEach(c=>c.classList.remove('active'));el.classList.add('active');updateOrders()}function updateOrders(){$('#orders-list').innerHTML=table(db.orders.filter(o=>(filter==='Semua'||o.status===filter)&&(o.id+' '+supplier(o.supplier)).toLowerCase().includes(query.toLowerCase())))}function openOrder(id){selected=id;page='detail';render();scrollTo(0,0)}
function detail(){const o=db.orders.find(o=>o.id===selected);if(!o)return navigate('orders');$('#main').innerHTML=heading('Detail Purchase Order','Informasi pesanan dan daftar barang.',`<button class="btn" onclick="navigate('orders')">← Kembali</button><button class="btn primary" onclick="statusForm()">✎ Ubah Status</button>`)+`<section class="panel detail"><div class="panel-head"><h2>${esc(o.id)}</h2>${badge(o.status)}</div><div class="detail-grid">${[['Supplier',supplier(o.supplier)],['Tanggal Purchase Order',date(o.date)],['Estimasi Tiba',date(o.arrival)],['Ringkasan',o.items.length+' item · '+total(o)+' qty']].map(([l,v])=>`<div><div class="info-label">${l}</div><div class="info-value">${esc(v)}</div></div>`).join('')}</div><div class="panel-head"><h2>Daftar Barang</h2><button class="text-link" onclick="exportOrders('${o.id}')">↓ Unduh CSV</button></div><div class="table-wrap"><table><thead><tr><th>No</th><th>Nama Barang</th><th>Qty</th></tr></thead><tbody>${o.items.map((i,n)=>`<tr><td>${n+1}</td><td>${esc(product(i.product))}</td><td>${i.qty}</td></tr>`).join('')}</tbody></table></div></section>`}
function show(content){$('#modal').innerHTML=content;$('#modal').showModal()}function closeModal(){$('#modal').close()}function actions(label='Simpan'){return `<div class="modal-actions"><button type="button" class="btn" onclick="closeModal()">Batal</button><button class="btn primary" type="submit">${label}</button></div>`}
function statusForm(){let o=db.orders.find(o=>o.id===selected);show(`<h2>Ubah Status PO</h2><p class="sub">${esc(o.id)}</p><form onsubmit="event.preventDefault();saveStatus()"><div class="form-group"><label>Status pesanan</label><select id="status">${['Draft','Sent','Confirmed','Delivered'].map(s=>`<option ${s===o.status?'selected':''}>${s}</option>`).join('')}</select></div>${actions()}</form>`)}function saveStatus(){const o=db.orders.find(o=>o.id===selected);o.status=$('#status').value;log(o.id+' → '+o.status,supplier(o.supplier));closeModal();render();toast('Status PO berhasil diperbarui')}
function orderForm(){if(!db.suppliers.length||!db.products.length)return toast('Tambahkan supplier dan produk terlebih dahulu');show(`<h2>Buat Purchase Order</h2><form onsubmit="event.preventDefault();saveOrder()"><div class="form-group"><label>Supplier</label><select id="po-supplier" onchange="$('#items').innerHTML='';addItem()">${db.suppliers.map(s=>`<option value="${esc(s.id)}">${esc(s.name)}</option>`).join('')}</select></div><div class="form-group"><label>Estimasi tiba</label><input id="po-arrival" type="date" value="${today()}" required></div><div class="form-group"><label>Produk & kuantitas</label><div id="items"></div><button type="button" class="text-link" onclick="addItem()">＋ Tambah barang</button></div>${actions('Buat PO')}</form>`);addItem()}
function addItem(){const list=db.products.filter(p=>p.supplier===$('#po-supplier').value);if(!list.length)return toast('Supplier ini belum memiliki produk');const el=document.createElement('div');el.className='item-line';el.innerHTML=`<select aria-label="Produk">${list.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('')}</select><input aria-label="Kuantitas" type="number" min="1" max="10000000" value="1" required><button type="button" onclick="this.parentElement.remove()" aria-label="Hapus barang">×</button>`;$('#items').append(el)}
function createOrder(supplierId,items,arrival){let n=db.orders.length+1,id;do{id='PO-'+today().replaceAll('-','')+'-'+String(n++).padStart(3,'0')}while(db.orders.some(o=>o.id===id));let o={id,date:today(),arrival:arrival||today(),supplier:supplierId,status:'Draft',items};db.orders.unshift(o);log(id+' dibuat',supplier(supplierId));return o}function saveOrder(){const items=[...document.querySelectorAll('.item-line')].map(e=>({product:e.querySelector('select').value,qty:Number(e.querySelector('input').value)}));if(!items.length)return toast('Tambahkan minimal satu barang');if(items.some(i=>!Number.isInteger(i.qty)||i.qty<1||i.qty>10000000))return toast('Kuantitas harus berupa bilangan bulat 1–10.000.000');const o=createOrder($('#po-supplier').value,items,$('#po-arrival').value);closeModal();openOrder(o.id);toast('Purchase Order berhasil dibuat')}
function master(){const isSup=page==='suppliers';$('#main').innerHTML=heading(isSup?'Master Supplier':'Master Produk',isSup?'Kelola partner pemasok untuk kebutuhan pembelian.':'Daftar produk yang tersedia untuk dipesan.',`<button class="btn primary" onclick="masterForm()">＋ Tambah ${isSup?'Supplier':'Produk'}</button>`)+`<div class="toolbar"><input class="search" aria-label="Cari" placeholder="⌕ Cari ${isSup?'supplier':'produk'}..." oninput="query=this.value;updateMaster()"></div><div id="master-list"></div>`;updateMaster()}
function updateMaster(){const isSup=page==='suppliers',list=(isSup?db.suppliers:db.products).filter(p=>(p.id+' '+p.name).toLowerCase().includes(query.toLowerCase()));$('#master-list').innerHTML=isSup?`<section class="panel"><div class="table-wrap"><table><thead><tr><th>Supplier</th><th>Kode</th><th>Produk</th><th></th></tr></thead><tbody>${list.map(s=>`<tr><td><strong>${esc(s.name)}</strong><small>Partner pembelian</small></td><td>${esc(s.id)}</td><td>${db.products.filter(p=>p.supplier===s.id).length} produk</td><td><button class="text-link" onclick="masterForm('${esc(s.id)}')">Edit →</button></td></tr>`).join('')}</tbody></table></div></section>`:`<div class="product-grid">${list.map(p=>`<section class="panel product"><div class="product-image">${esc(p.emoji||'📦')}</div><h3>${esc(p.name)}</h3><p>${esc(p.id)}</p><p>${esc(supplier(p.supplier))}</p>${badge('Aktif')}<button style="float:right" class="text-link" onclick="masterForm('${esc(p.id)}')">Edit →</button></section>`).join('')}</div>`;if(!list.length)$('#master-list').innerHTML='<div class="empty"><h2>Data tidak ditemukan</h2><p>Tambahkan data baru atau ubah pencarian.</p></div>'}
function masterForm(id=''){const s=page==='suppliers',p=(s?db.suppliers:db.products).find(p=>p.id===id);show(`<h2>${p?'Edit':'Tambah'} ${s?'Supplier':'Produk'}</h2><form onsubmit="event.preventDefault();saveMaster('${esc(id)}')"><div class="form-group"><label>${s?'Kode Supplier':'Barcode / Kode Produk'}</label><input id="master-id" value="${esc(p?.id||'')}" required pattern="[A-Za-z0-9_-]+" ${p?'readonly':''}></div><div class="form-group"><label>Nama ${s?'Supplier':'Produk'}</label><input id="master-name" value="${esc(p?.name||'')}" required maxlength="120"></div>${!s?`<div class="form-group"><label>Supplier</label><select id="master-supplier" required>${db.suppliers.map(x=>`<option value="${esc(x.id)}" ${x.id===p?.supplier?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div>`:''}${actions()}</form>`)}
function saveMaster(id){const s=page==='suppliers',list=s?db.suppliers:db.products,newId=$('#master-id').value.trim(),name=$('#master-name').value.trim();if(!name||name.length>120)return toast('Nama wajib diisi, maksimal 120 karakter');if(!/^[A-Za-z0-9_-]{1,120}$/.test(newId))return toast('Kode hanya boleh berisi huruf, angka, tanda minus, atau garis bawah');if(!s&&id&&db.orders.some(o=>o.items.some(i=>i.product===id)&&o.supplier!==$('#master-supplier').value))return toast('Supplier produk yang sudah dipakai dalam PO tidak dapat diubah');if(!id&&list.some(x=>x.id===newId))return toast('Kode sudah digunakan');const value={id:newId,name,...(!s?{supplier:$('#master-supplier').value,emoji:'📦'}:{})};if(id)Object.assign(list.find(x=>x.id===id),value);else list.push(value);log((s?'Supplier':'Produk')+(id?' diperbarui':' ditambahkan'),name);closeModal();render();toast('Data berhasil disimpan')}
function importPage(){$('#main').innerHTML=heading('Import Excel','Ubah daftar pembelian menjadi PO dengan lebih cepat.')+`<section class="panel import-box"><span class="eyebrow">UPLOAD → REVIEW → SELESAI</span><h2 style="margin-top:15px;font-size:21px">Import Data Purchase Order</h2><p class="sub">Gunakan template agar data barang terbaca dengan benar.</p><div class="upload"><span class="symbol">▧</span><h3 style="margin-top:20px">Pilih file Excel atau CSV</h3><p class="sub">.xlsx, .xls, .csv · Maksimal 10.000 baris / 5 MB</p><button class="btn primary" onclick="$('#file').click()">⇧ Pilih File</button><input id="file" type="file" accept=".xlsx,.xls,.csv" hidden onchange="readFile(this.files[0])"></div><button class="text-link" style="margin-top:18px" onclick="downloadTemplate()">↓ Unduh template CSV</button><div class="format"><b>Format kolom yang diperlukan</b><br>supplier, kode_produk, nama_produk, qty<br>Supplier baru dan produk baru akan ditambahkan otomatis.<br>Periksa data sebelum membuat PO. Satu PO dibuat untuk setiap supplier.</div><div id="import-review"></div></section>`}
function download(name,content,type='text/csv;charset=utf-8'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}function downloadTemplate(){download('template-purchase-order.csv','supplier,kode_produk,nama_produk,qty\nPT. Sumber Rezeki,8992711234567,Tepung Terigu Segitiga Biru,20\nPT. Sumber Rezeki,8992717654321,Gula Pasir Gulaku,15\n')}
async function readFile(file){if(!file)return;if(file.size>5*1024*1024)return toast('Ukuran file maksimal 5 MB');if(!window.XLSX)return toast('Pembaca Excel belum termuat. Periksa koneksi lalu coba lagi.');try{const book=XLSX.read(await file.arrayBuffer(),{type:'array'}),data=XLSX.utils.sheet_to_json(book.Sheets[book.SheetNames[0]],{defval:''});if(!data.length||data.length>10000)throw Error('File harus berisi 1–10.000 baris.');imported=data.map((r,i)=>{if(!/^[A-Za-z0-9_-]{1,120}$/.test(String(r.kode_produk))||String(r.nama_produk).trim().length>120||String(r.supplier).trim().length>120||Number(r.qty)>10000000||!String(r.supplier).trim()||!String(r.kode_produk).trim()||!String(r.nama_produk).trim()||!Number.isInteger(Number(r.qty))||Number(r.qty)<=0||!('supplier'in r)||!('kode_produk'in r)||!('nama_produk'in r))throw Error('Baris '+(i+2)+': supplier, kode_produk, nama_produk, dan qty positif wajib diisi.');return {supplier:String(r.supplier).trim(),id:String(r.kode_produk).trim(),name:String(r.nama_produk).trim(),qty:Number(r.qty)}});const seen=new Map();for(const r of imported){const existing=db.products.find(p=>p.id===r.id);if(existing&&supplier(existing.supplier)!==r.supplier)throw Error('Produk '+r.id+' sudah terdaftar pada supplier lain.');if(seen.has(r.id)&&seen.get(r.id)!==r.supplier)throw Error('Kode produk '+r.id+' digunakan oleh beberapa supplier.');seen.set(r.id,r.supplier)}$('#import-review').innerHTML=`<div class="format"><b>✓ ${esc(file.name)} siap diproses</b><br>${imported.length} baris barang · ${imported.reduce((s,r)=>s+r.qty,0)} qty · ${new Set(imported.map(r=>r.supplier)).size} supplier</div><div class="table-wrap"><table><thead><tr><th>Produk</th><th>Supplier</th><th>Qty</th></tr></thead><tbody>${imported.slice(0,20).map(r=>`<tr><td>${esc(r.name)}</td><td>${esc(r.supplier)}</td><td>${r.qty}</td></tr>`).join('')}</tbody></table></div><p class="sub">Menampilkan hingga 20 baris pertama.</p><button class="btn primary" style="margin-top:18px" onclick="commitImport()">Buat PO per Supplier</button>`}catch(e){imported=[];$('#import-review').innerHTML='';toast(e.message||'File tidak dapat dibaca')}}
function commitImport(){if(!imported.length)return;const groups=new Map();for(const r of imported){let s=db.suppliers.find(s=>s.name===r.supplier);if(!s){let n=db.suppliers.length+1,id;do{id='SUP'+String(n++).padStart(3,'0')}while(db.suppliers.some(s=>s.id===id));s={id,name:r.supplier};db.suppliers.push(s)}if(!db.products.some(p=>p.id===r.id))db.products.push({id:r.id,name:r.name,supplier:s.id,emoji:'📦'});if(!groups.has(s.id))groups.set(s.id,[]);groups.get(s.id).push({product:r.id,qty:r.qty})}for(const [s,items] of groups)createOrder(s,items);log('Import Excel selesai',imported.length+' baris barang diproses');imported=[];navigate('orders');toast(groups.size+' PO berhasil dibuat')}
function csv(v){return '"'+String(v).replaceAll('"','""')+'"'}function exportOrders(id){const list=id?db.orders.filter(o=>o.id===id):db.orders;download('purchase-orders.csv','\ufeff'+[['Nomor PO','Tanggal','Supplier','Status','Produk','Qty'],...list.flatMap(o=>o.items.map(i=>[o.id,o.date,supplier(o.supplier),o.status,product(i.product),i.qty]))].map(r=>r.map(csv).join(',')).join('\r\n'))}
function activityPage(){$('#main').innerHTML=heading('Aktivitas Terbaru','Riwayat perubahan dan aktivitas pembelian Anda.')+`<section class="panel profile">${activityList()}</section>`}
function profile(){$('#main').innerHTML=heading('Profil & Pengaturan','Kelola data workspace Anda.')+`<section class="panel profile"><div class="profile-row"><span><b>Tim Purchasing</b><p class="sub">Kedai UPU · Purchasing</p></span><span class="avatar" style="display:grid;place-items:center">TP</span></div><button class="profile-row" onclick="backup()">↓ Unduh cadangan data <span>›</span></button><button class="profile-row" onclick="$('#restore').click()">↑ Pulihkan cadangan data <span>›</span></button><input hidden type="file" id="restore" accept=".json" onchange="restoreData(this.files[0])"><div class="profile-row">Penyimpanan <span class="badge Confirmed">Browser perangkat ini</span></div><button class="profile-row" onclick="about()">Tentang Aplikasi <span>›</span></button></section><p class="sub">Data tersimpan lokal dan belum tersinkron antarperangkat.<br>Unduh cadangan secara berkala untuk menyimpan salinan data Anda.</p>`}function backup(){download('kedai-upu-backup.json',JSON.stringify(db,null,2),'application/json');toast('Cadangan data diunduh')}function about(){show('<h2>Kedai UPU PO</h2><p class="sub">Aplikasi manajemen purchase order versi 1.0.<br>Dibuat untuk memudahkan pembelian, pengelolaan supplier, produk, dan impor Excel. Data awal adalah contoh yang dapat Anda gunakan untuk mencoba aplikasi.</p><div class="modal-actions"><button class="btn primary" onclick="closeModal()">Tutup</button></div>')}
async function restoreData(file){if(!file)return;try{if(file.size>10*1024*1024)throw Error();const data=JSON.parse(await file.text());PurchasingData.validate(data);show(`<h2>Pulihkan cadangan?</h2><p class="sub">Data saat ini akan diganti dengan ${data.orders.length} PO, ${data.suppliers.length} supplier, dan ${data.products.length} produk dari cadangan ini. Unduh cadangan saat ini sebelum melanjutkan.</p><div class="modal-actions"><button class="btn" onclick="backup()">Unduh cadangan</button><button class="btn" onclick="closeModal()">Batal</button><button class="btn primary" id="confirm-restore">Pulihkan</button></div>`);$('#confirm-restore').onclick=()=>{const apply=()=>{db=data;save();closeModal();render();toast('Cadangan berhasil dipulihkan')};return window.Cloud?Cloud.mutate(apply):apply()}}catch(error){toast(error.message||'Format cadangan tidak valid')}}
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});render();
